		Class<?> subclass = SubclassWithNonStaticPackagePrivateTempDirField.class;
		Field nonStaticField = subclass.getDeclaredField(TEMP_DIR);

		// Prerequisite
		var fields = findFields(superclass, ReflectionUtils::isStatic, TOP_DOWN);
