	class IsClassAssignableToClassTests {

		@Test
		void isAssignableToForNullSourceType() {
			assertThatExceptionOfType(PreconditionViolationException.class)//
					.isThrownBy(() -> ReflectionUtils.isAssignableTo(null, getClass()))//
