			assertThat(findNestedClasses(classWithInvalidNestedClassFile)).isEmpty();
			// @formatter:off
			var logMessage = listener.stream(ReflectionUtils.class, Level.FINE)
					.findFirst()
					.map(LogRecord::getMessage)
					.orElse("didn't find log record");
