			this.beforeAllCalls = 0;
			this.beforeEachCalls = 0;
			this.afterEachCalls = 0;
			this.afterAllCalls = 0;
		}

		public void incrementBeforeAllCalls() {
			beforeAllCalls++;
		}

		public void incrementBeforeEachCalls() {
			beforeEachCalls++;
		}

		public void incrementAfterEachCalls() {
