methodSignature: org.junit.platform.commons.util.ReflectionUtilsTests#assertNestedCycle
 methodBody: private void assertNestedCycle(Class<?> start, Class<?> from, Class<?> to) {
assertThatExceptionOfType(JUnitException.class).as("expected cycle from %s to %s",from.getSimpleName(),to.getSimpleName()).isThrownBy(() -> findNestedClasses(start)).withMessageMatching(String.format("Detected cycle in inner class hierarchy between .+%s and .+%s",from.getSimpleName(),to.getSimpleName()));
}

